// Unoptimized version
function SlowList({ items }) {
  const handleSort = () => items.sort((a, b) => a.value - b.value);

  return (
    <div>
      {items.map((item) => (
        <ListItem key={item.id} item={item} onSort={handleSort} />
      ))}
    </div>
  );
}

// Optimized version
const ListItem = React.memo(({ item, onSort }) => {
  return <div onClick={onSort}>{item.name}</div>;
});

function OptimizedList({ items }) {
  const handleSort = useCallback(() => {
    return [...items].sort((a, b) => a.value - b.value);
  }, [items]);

  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => a.value - b.value);
  }, [items]);

  return (
    <div>
      {sortedItems.map((item) => (
        <ListItem key={item.id} item={item} onSort={handleSort} />
      ))}
    </div>
  );
}

// Key principles:
// 1. React.memo prevents re-render if props didn't change
// 2. useCallback maintains stable function reference across renders
// 3. useMemo caches expensive computations
// 4. All three require proper dependency arrays
// 5. Use React DevTools Profiler to measure impact
// 6. Profile before optimizing - don't optimize prematurely
